window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-482fe380c7740a11"]={"versions": [{"id": "FIG-482fe380c7740a11", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Phasen- und Ausführungsablaufdiagramm (Execution Timing & Barrier Diagram) der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert die deterministische, phasenbasierte Ausführungsreihenfolge und Synchronisationsbarrieren von <code>ExecutableEntities</code> während eines synchronen Moduswechsels (<em>Synchronous Mode Transition</em>) innerhalb einer <code>ModeDeclarationGroup</code> gemäß <code>AUTOSAR_SWS_RTE</code>. Es definiert den harten Ausschluss von Nebenläufigkeit zwischen inkompatiblen Betriebsmodi.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutableEntity</code>:</strong> Abstrakte Ausführungseinheit der AUTOSAR-Architektur (konkretisiert als <code>RunnableEntity</code> in Software Components bzw. <code>BswSchedulableEntity</code> / <code>BswModuleEntity</code> in Basissoftware-Modulen).</li>\n<li><strong>Mode Disabling Dependent <code>ExecutableEntities</code>:</strong></li>\n<li><em>Quellmodus (Blau):</em> Entitäten, deren Ausführung an den Verbleib im Ausgangsmodus gebunden ist (modelliert über <code>ModeDisablingDependency</code> bzw. Deaktivierung bei Modusaustritt).</li>\n<li><em>Zielmodus (Pink):</em> Entitäten des Zielmodus, die erst nach vollständiger Modusetablierung aktivierbar sind.</li>\n<li><strong>Moduswechsel-gesteuerte <code>ExecutableEntities</code> (Event-Triggered):</strong></li>\n<li><em><code>OnExit</code> (Rot):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_EXIT</code> beim Verlassen des alten Modus.</li>\n<li><em><code>OnTransition</code> (Gelb):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_TRANSITION</code> für den spezifischen Zustandsübergang $(Mode_{alt} \\rightarrow Mode_{neu})$.</li>\n<li><em><code>OnEntry</code> (Grün):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_ENTRY</code> beim Eintreten in den Zielmodus.</li>\n<li><strong>Trigger & Kontrollinstanz:</strong></li>\n<li><code>mode switch indication</code>: Signal/API-Trigger (z. B. via <code>Rte_Switch_&lt;p&gt;_&lt;o&gt;()</code>), initiiert durch einen Mode Manager (z. B. BswM oder SW-C).</li>\n<li>Horizontale gestrichelte Linie: RTE-Aktivierungs-/Scheduler-Achse bzw. Task-Level-Ausführungsband.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Mode Switch Indication & Completion Barrier:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mit Eintreffen der Indikation wird die Neuaktivierung aller blau markierten Entitäten des Quellmodus sofort unterbunden.</li>\n<li>Bereits instanziierte/laufende blaue Entitäten dürfen ihre aktuelle Ausführung vollständig beenden (überlappender blauer Balken rechts der Indikationslinie).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 – OnExit (Rot):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erst nach Terminierung der letzten aktiven Quellmodus-Entität starten die <code>OnExit</code>-Runnables.</li>\n<li>Dient dem Aufräumen, Sichern von Zuständen und Deinitialisieren modusspezifischer Ressourcen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 – OnTransition (Gelb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet strikt sequenziell nach vollständiger Terminierung aller <code>OnExit</code>-Entitäten.</li>\n<li>Führt zustandsübergreifende Transformationen und Umkonfigurationen durch.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 – OnEntry (Grün):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet erst nach Abschluss aller <code>OnTransition</code>-Entitäten.</li>\n<li>Dient der Initialisierung von Datenstrukturen und Vorbereitung für den Zielmodus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 – Zielmodus-Freigabe (Pink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abschluss aller <code>OnEntry</code>-Entitäten ist der synchrone Moduswechsel abgeschlossen.</li>\n<li>Erst ab dieser Barriere gibt die RTE die periodischen oder ereignisgesteuerten <code>ExecutableEntities</code> des Zielmodus frei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Blockierender API-Vertrag:</strong> Bei synchronem Moduswechsel (<code>Rte_Switch</code>) kehrt der Aufruf erst nach vollständiger Abarbeitung der <code>OnEntry</code>-Phase zum Aufrufer zurück.</li>\n<li><strong>WCET- und Latenz-Budgetierung:</strong> Die Gesamtlatenz des Moduswechsels beträgt:</li>\n</ul>\n<p class=\"fig-p\">$$t_{switch} = t_{drain}(Mode_{alt}) + \\sum t_{exec}(OnExit) + \\sum t_{exec}(OnTransition) + \\sum t_{exec}(OnEntry)$$</p>\n<p class=\"fig-p\">Entwickler dürfen in Exit/Transition/Entry-Runnables keine blockierenden Operationen oder zeitintensiven Schleifen implementieren, um Task-Überläufe und Watchdog-Verletzungen zu vermeiden.</p>\n<ul class=\"fig-list\">\n<li><strong>Task-Mapping-Restriktionen:</strong> Verteilen sich die beteiligten Runnables über mehrere OS-Tasks oder Cores, muss der RTE-Generator Synchronisationsmechanismen (OS-Events, Spinlocks, Inter-Core-IPIs) injizieren. Zyklische Abhängigkeiten zwischen Tasks verschiedener Phasen führen zu Deadlocks.</li>\n<li><strong>Shared-Data-Sicherheit:</strong> Da die Phasen wechselseitig exklusiv durch Barrieren getrennt sind, sind Datenzugriffe zwischen Quell- und Zielmodus-Runnables inhärent race-condition-frei gegenüber dem Moduswechsel; Semaphore für Modusvariablen innerhalb dieser Phasen sind obsolet.</li>\n</ul>"}, {"id": "FIG-67d04b0db797c7f5", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Phasen- und Ausführungsablaufdiagramm (Execution Timing & Barrier Diagram) der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert die deterministische, phasenbasierte Ausführungsreihenfolge und Synchronisationsbarrieren von <code>ExecutableEntities</code> während eines synchronen Moduswechsels (<em>Synchronous Mode Transition</em>) innerhalb einer <code>ModeDeclarationGroup</code> gemäß <code>AUTOSAR_SWS_RTE</code>. Es definiert den harten Ausschluss von Nebenläufigkeit zwischen inkompatiblen Betriebsmodi.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutableEntity</code>:</strong> Abstrakte Ausführungseinheit der AUTOSAR-Architektur (konkretisiert als <code>RunnableEntity</code> in Software Components bzw. <code>BswSchedulableEntity</code> / <code>BswModuleEntity</code> in Basissoftware-Modulen).</li>\n<li><strong>Mode Disabling Dependent <code>ExecutableEntities</code>:</strong></li>\n<li><em>Quellmodus (Blau):</em> Entitäten, deren Ausführung an den Verbleib im Ausgangsmodus gebunden ist (modelliert über <code>ModeDisablingDependency</code> bzw. Deaktivierung bei Modusaustritt).</li>\n<li><em>Zielmodus (Pink):</em> Entitäten des Zielmodus, die erst nach vollständiger Modusetablierung aktivierbar sind.</li>\n<li><strong>Moduswechsel-gesteuerte <code>ExecutableEntities</code> (Event-Triggered):</strong></li>\n<li><em><code>OnExit</code> (Rot):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_EXIT</code> beim Verlassen des alten Modus.</li>\n<li><em><code>OnTransition</code> (Gelb):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_TRANSITION</code> für den spezifischen Zustandsübergang $(Mode_{alt} \\rightarrow Mode_{neu})$.</li>\n<li><em><code>OnEntry</code> (Grün):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_ENTRY</code> beim Eintreten in den Zielmodus.</li>\n<li><strong>Trigger & Kontrollinstanz:</strong></li>\n<li><code>mode switch indication</code>: Signal/API-Trigger (z. B. via <code>Rte_Switch_&lt;p&gt;_&lt;o&gt;()</code>), initiiert durch einen Mode Manager (z. B. BswM oder SW-C).</li>\n<li>Horizontale gestrichelte Linie: RTE-Aktivierungs-/Scheduler-Achse bzw. Task-Level-Ausführungsband.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Mode Switch Indication & Completion Barrier:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mit Eintreffen der Indikation wird die Neuaktivierung aller blau markierten Entitäten des Quellmodus sofort unterbunden.</li>\n<li>Bereits instanziierte/laufende blaue Entitäten dürfen ihre aktuelle Ausführung vollständig beenden (überlappender blauer Balken rechts der Indikationslinie).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 – OnExit (Rot):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erst nach Terminierung der letzten aktiven Quellmodus-Entität starten die <code>OnExit</code>-Runnables.</li>\n<li>Dient dem Aufräumen, Sichern von Zuständen und Deinitialisieren modusspezifischer Ressourcen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 – OnTransition (Gelb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet strikt sequenziell nach vollständiger Terminierung aller <code>OnExit</code>-Entitäten.</li>\n<li>Führt zustandsübergreifende Transformationen und Umkonfigurationen durch.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 – OnEntry (Grün):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet erst nach Abschluss aller <code>OnTransition</code>-Entitäten.</li>\n<li>Dient der Initialisierung von Datenstrukturen und Vorbereitung für den Zielmodus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 – Zielmodus-Freigabe (Pink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abschluss aller <code>OnEntry</code>-Entitäten ist der synchrone Moduswechsel abgeschlossen.</li>\n<li>Erst ab dieser Barriere gibt die RTE die periodischen oder ereignisgesteuerten <code>ExecutableEntities</code> des Zielmodus frei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Blockierender API-Vertrag:</strong> Bei synchronem Moduswechsel (<code>Rte_Switch</code>) kehrt der Aufruf erst nach vollständiger Abarbeitung der <code>OnEntry</code>-Phase zum Aufrufer zurück.</li>\n<li><strong>WCET- und Latenz-Budgetierung:</strong> Die Gesamtlatenz des Moduswechsels beträgt:</li>\n</ul>\n<p class=\"fig-p\">$$t_{switch} = t_{drain}(Mode_{alt}) + \\sum t_{exec}(OnExit) + \\sum t_{exec}(OnTransition) + \\sum t_{exec}(OnEntry)$$</p>\n<p class=\"fig-p\">Entwickler dürfen in Exit/Transition/Entry-Runnables keine blockierenden Operationen oder zeitintensiven Schleifen implementieren, um Task-Überläufe und Watchdog-Verletzungen zu vermeiden.</p>\n<ul class=\"fig-list\">\n<li><strong>Task-Mapping-Restriktionen:</strong> Verteilen sich die beteiligten Runnables über mehrere OS-Tasks oder Cores, muss der RTE-Generator Synchronisationsmechanismen (OS-Events, Spinlocks, Inter-Core-IPIs) injizieren. Zyklische Abhängigkeiten zwischen Tasks verschiedener Phasen führen zu Deadlocks.</li>\n<li><strong>Shared-Data-Sicherheit:</strong> Da die Phasen wechselseitig exklusiv durch Barrieren getrennt sind, sind Datenzugriffe zwischen Quell- und Zielmodus-Runnables inhärent race-condition-frei gegenüber dem Moduswechsel; Semaphore für Modusvariablen innerhalb dieser Phasen sind obsolet.</li>\n</ul>"}, {"id": "FIG-55ff7f9ff8915e79", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Phasen- und Ausführungsablaufdiagramm (Execution Timing & Barrier Diagram) der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert die deterministische, phasenbasierte Ausführungsreihenfolge und Synchronisationsbarrieren von <code>ExecutableEntities</code> während eines synchronen Moduswechsels (<em>Synchronous Mode Transition</em>) innerhalb einer <code>ModeDeclarationGroup</code> gemäß <code>AUTOSAR_SWS_RTE</code>. Es definiert den harten Ausschluss von Nebenläufigkeit zwischen inkompatiblen Betriebsmodi.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutableEntity</code>:</strong> Abstrakte Ausführungseinheit der AUTOSAR-Architektur (konkretisiert als <code>RunnableEntity</code> in Software Components bzw. <code>BswSchedulableEntity</code> / <code>BswModuleEntity</code> in Basissoftware-Modulen).</li>\n<li><strong>Mode Disabling Dependent <code>ExecutableEntities</code>:</strong></li>\n<li><em>Quellmodus (Blau):</em> Entitäten, deren Ausführung an den Verbleib im Ausgangsmodus gebunden ist (modelliert über <code>ModeDisablingDependency</code> bzw. Deaktivierung bei Modusaustritt).</li>\n<li><em>Zielmodus (Pink):</em> Entitäten des Zielmodus, die erst nach vollständiger Modusetablierung aktivierbar sind.</li>\n<li><strong>Moduswechsel-gesteuerte <code>ExecutableEntities</code> (Event-Triggered):</strong></li>\n<li><em><code>OnExit</code> (Rot):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_EXIT</code> beim Verlassen des alten Modus.</li>\n<li><em><code>OnTransition</code> (Gelb):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_TRANSITION</code> für den spezifischen Zustandsübergang $(Mode_{alt} \\rightarrow Mode_{neu})$.</li>\n<li><em><code>OnEntry</code> (Grün):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_ENTRY</code> beim Eintreten in den Zielmodus.</li>\n<li><strong>Deaktivierungsbereiche (Mode Disabling Spans):</strong></li>\n<li><em><code>mode disabling for “old mode”</code> (Pinker Pfeil):</em> Horizontales Intervall, das die Gültigkeitsdauer der Modusdeaktivierung für den Quellmodus abbildet und bis zum Abschluss der <code>OnEntry</code>-Phase reicht.</li>\n<li><em><code>mode disabling for “new mode”</code> (Blauer Pfeil):</em> Horizontales Intervall, das die Gültigkeitsdauer der Modusdeaktivierung für den Zielmodus abbildet, beginnend ab der vollständigen Terminierung der letzten Quellmodus-Entität.</li>\n<li><strong>Trigger & Kontrollgrenzen:</strong></li>\n<li><code>mode switch indication</code>: Vertikale Indikationslinie für den Trigger des Moduswechsels (z. B. via <code>Rte_Switch_&lt;p&gt;_&lt;o&gt;()</code>), initiiert durch einen Mode Manager (z. B. BswM oder SW-C).</li>\n<li>Gepunktete Barriere-Linie: Markiert den exakten Abschluss der letzten Quellmodus-Entität und den Beginn der Übergangsphasen sowie des Zielmodus-Disablings.</li>\n<li>Horizontale gestrichelte Linie: RTE-Aktivierungs-/Scheduler-Achse bzw. Task-Level-Ausführungsband.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Mode Switch Indication & Completion Barrier:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mit Eintreffen der Indikation (<code>mode switch indication</code>) wird die Neuaktivierung aller blau markierten Entitäten des Quellmodus sofort unterbunden. Das <code>mode disabling for “old mode”</code> bleibt weiterhin aktiv.</li>\n<li>Bereits instanziierte/laufende blaue Entitäten dürfen ihre aktuelle Ausführung vollständig beenden (gepunktet berandeter Auslauf über die Indikationslinie hinaus).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 – OnExit (Rot) & New Mode Disabling Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>An der gepunkteten Barriere nach Terminierung der letzten aktiven Quellmodus-Entität starten die <code>OnExit</code>-Runnables.</li>\n<li>Zeitgleich beginnt an dieser Barriere das <code>mode disabling for “new mode”</code>, sodass für den Zielmodus gesperrte Entitäten ab hier blockiert sind.</li>\n<li>Dient dem Aufräumen, Sichern von Zuständen und Deinitialisieren modusspezifischer Ressourcen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 – OnTransition (Gelb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet strikt sequenziell nach vollständiger Terminierung aller <code>OnExit</code>-Entitäten.</li>\n<li>Führt zustandsübergreifende Transformationen und Umkonfigurationen durch.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 – OnEntry (Grün):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet erst nach Abschluss aller <code>OnTransition</code>-Entitäten.</li>\n<li>Dient der Initialisierung von Datenstrukturen und Vorbereitung für den Zielmodus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 – Zielmodus-Freigabe & Ende des Old Mode Disabling (Pink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abschluss aller <code>OnEntry</code>-Entitäten endet das <code>mode disabling for “old mode”</code> an der vertikalen Barriere; der synchrone Moduswechsel ist vollendet.</li>\n<li>Erst ab dieser Barriere gibt die RTE die periodischen oder ereignisgesteuerten <code>ExecutableEntities</code> des Zielmodus frei, während das <code>mode disabling for “new mode”</code> fortbesteht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Blockierender API-Vertrag:</strong> Bei synchronem Moduswechsel (<code>Rte_Switch</code>) kehrt der Aufruf erst nach vollständiger Abarbeitung der <code>OnEntry</code>-Phase zum Aufrufer zurück.</li>\n<li><strong>WCET- und Latenz-Budgetierung:</strong> Die Gesamtlatenz des Moduswechsels beträgt:</li>\n</ul>\n<p class=\"fig-p\">$$t_{switch} = t_{drain}(Mode_{alt}) + \\sum t_{exec}(OnExit) + \\sum t_{exec}(OnTransition) + \\sum t_{exec}(OnEntry)$$</p>\n<p class=\"fig-p\">Entwickler dürfen in Exit/Transition/Entry-Runnables keine blockierenden Operationen oder zeitintensiven Schleifen implementieren, um Task-Überläufe und Watchdog-Verletzungen zu vermeiden.</p>\n<ul class=\"fig-list\">\n<li><strong>Task-Mapping-Restriktionen:</strong> Verteilen sich die beteiligten Runnables über mehrere OS-Tasks oder Cores, muss der RTE-Generator Synchronisationsmechanismen (OS-Events, Spinlocks, Inter-Core-IPIs) injizieren. Zyklische Abhängigkeiten zwischen Tasks verschiedener Phasen führen zu Deadlocks.</li>\n<li><strong>Shared-Data-Sicherheit:</strong> Da die Phasen wechselseitig exklusiv durch Barrieren getrennt sind, sind Datenzugriffe zwischen Quell- und Zielmodus-Runnables inhärent race-condition-frei gegenüber dem Moduswechsel; Semaphore für Modusvariablen innerhalb dieser Phasen sind obsolet.</li>\n</ul>"}, {"id": "FIG-e31faa450d5a3ef0", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Phasen- und Ausführungsablaufdiagramm (Execution Timing & Barrier Diagram) der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Funktionaler Kontext:</strong> Spezifiziert die deterministische, phasenbasierte Ausführungsreihenfolge und Synchronisationsbarrieren von <code>ExecutableEntities</code> während eines synchronen Moduswechsels (<em>Synchronous Mode Transition</em>) innerhalb einer <code>ModeDeclarationGroup</code> gemäß <code>AUTOSAR_SWS_RTE</code>. Es definiert den harten Ausschluss von Nebenläufigkeit zwischen inkompatiblen Betriebsmodi.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>ExecutableEntity</code>:</strong> Abstrakte Ausführungseinheit der AUTOSAR-Architektur (konkretisiert als <code>RunnableEntity</code> in Software Components bzw. <code>BswSchedulableEntity</code> / <code>BswModuleEntity</code> in Basissoftware-Modulen).</li>\n<li><strong>Mode Disabling Dependent <code>ExecutableEntities</code>:</strong></li>\n<li><em>Quellmodus (Blau):</em> Entitäten, deren Ausführung an den Verbleib im Ausgangsmodus gebunden ist (modelliert über <code>ModeDisablingDependency</code> bzw. Deaktivierung bei Modusaustritt).</li>\n<li><em>Zielmodus (Pink):</em> Entitäten des Zielmodus, die erst nach vollständiger Modusetablierung aktivierbar sind.</li>\n<li><strong>Moduswechsel-gesteuerte <code>ExecutableEntities</code> (Event-Triggered):</strong></li>\n<li><em><code>OnExit</code> (Rot):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_EXIT</code> beim Verlassen des alten Modus.</li>\n<li><em><code>OnTransition</code> (Gelb):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_TRANSITION</code> für den spezifischen Zustandsübergang $(Mode_{alt} \\rightarrow Mode_{neu})$.</li>\n<li><em><code>OnEntry</code> (Grün):</em> Getriggert durch <code>(Swc)ModeSwitchEvent</code> mit Konfiguration <code>activation = ON_ENTRY</code> beim Eintreten in den Zielmodus.</li>\n<li><strong>Deaktivierungsbereiche (Mode Disabling Spans):</strong></li>\n<li><em><code>mode disabling for “old mode”</code> (Pinker Pfeil):</em> Horizontales Intervall, das die Gültigkeitsdauer der Modusdeaktivierung für den Quellmodus abbildet und bis zum Abschluss der <code>OnEntry</code>-Phase reicht.</li>\n<li><em><code>mode disabling for “new mode”</code> (Blauer Pfeil):</em> Horizontales Intervall, das die Gültigkeitsdauer der Modusdeaktivierung für den Zielmodus abbildet, beginnend ab der vollständigen Terminierung der letzten Quellmodus-Entität.</li>\n<li><strong>Trigger & Kontrollgrenzen:</strong></li>\n<li><code>mode switch indication</code>: Vertikale Indikationslinie für den Trigger des Moduswechsels (z. B. via <code>Rte_Switch_&lt;p&gt;_&lt;o&gt;()</code>), initiiert durch einen Mode Manager (z. B. BswM oder SW-C).</li>\n<li>Gepunktete Barriere-Linie: Markiert den exakten Abschluss der letzten Quellmodus-Entität und den Beginn der Übergangsphasen sowie des Zielmodus-Disablings.</li>\n<li>Horizontale gestrichelte Linie: RTE-Aktivierungs-/Scheduler-Achse bzw. Task-Level-Ausführungsband.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Mode Switch Indication & Completion Barrier:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Mit Eintreffen der Indikation (<code>mode switch indication</code>) wird die Neuaktivierung aller blau markierten Entitäten des Quellmodus sofort unterbunden. Das <code>mode disabling for “old mode”</code> bleibt weiterhin aktiv.</li>\n<li>Bereits instanziierte/laufende blaue Entitäten dürfen ihre aktuelle Ausführung vollständig beenden (gepunktet berandeter Auslauf über die Indikationslinie hinaus).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 1 – OnExit (Rot) & New Mode Disabling Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>An der gepunkteten Barriere nach Terminierung der letzten aktiven Quellmodus-Entität starten die <code>OnExit</code>-Runnables.</li>\n<li>Zeitgleich beginnt an dieser Barriere das <code>mode disabling for “new mode”</code>, sodass für den Zielmodus gesperrte Entitäten ab hier blockiert sind.</li>\n<li>Dient dem Aufräumen, Sichern von Zuständen und Deinitialisieren modusspezifischer Ressourcen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 2 – OnTransition (Gelb):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet strikt sequenziell nach vollständiger Terminierung aller <code>OnExit</code>-Entitäten.</li>\n<li>Führt zustandsübergreifende Transformationen und Umkonfigurationen durch.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 3 – OnEntry (Grün):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Startet erst nach Abschluss aller <code>OnTransition</code>-Entitäten.</li>\n<li>Dient der Initialisierung von Datenstrukturen und Vorbereitung für den Zielmodus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Phase 4 – Zielmodus-Freigabe & Ende des Old Mode Disabling (Pink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Abschluss aller <code>OnEntry</code>-Entitäten endet das <code>mode disabling for “old mode”</code> an der vertikalen Barriere; der synchrone Moduswechsel ist vollendet.</li>\n<li>Erst ab dieser Barriere gibt die RTE die periodischen oder ereignisgesteuerten <code>ExecutableEntities</code> des Zielmodus frei, während das <code>mode disabling for “new mode”</code> fortbesteht.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Blockierender API-Vertrag:</strong> Bei synchronem Moduswechsel (<code>Rte_Switch</code>) kehrt der Aufruf erst nach vollständiger Abarbeitung der <code>OnEntry</code>-Phase zum Aufrufer zurück.</li>\n<li><strong>WCET- und Latenz-Budgetierung:</strong> Die Gesamtlatenz des Moduswechsels beträgt:</li>\n</ul>\n<p class=\"fig-p\">$$t_{switch} = t_{drain}(Mode_{alt}) + \\sum t_{exec}(OnExit) + \\sum t_{exec}(OnTransition) + \\sum t_{exec}(OnEntry)$$</p>\n<p class=\"fig-p\">Entwickler dürfen in Exit/Transition/Entry-Runnables keine blockierenden Operationen oder zeitintensiven Schleifen implementieren, um Task-Überläufe und Watchdog-Verletzungen zu vermeiden.</p>\n<ul class=\"fig-list\">\n<li><strong>Task-Mapping-Restriktionen:</strong> Verteilen sich die beteiligten Runnables über mehrere OS-Tasks oder Cores, muss der RTE-Generator Synchronisationsmechanismen (OS-Events, Spinlocks, Inter-Core-IPIs) injizieren. Zyklische Abhängigkeiten zwischen Tasks verschiedener Phasen führen zu Deadlocks.</li>\n<li><strong>Shared-Data-Sicherheit:</strong> Da die Phasen wechselseitig exklusiv durch Barrieren getrennt sind, sind Datenzugriffe zwischen Quell- und Zielmodus-Runnables inhärent race-condition-frei gegenüber dem Moduswechsel; Semaphore für Modusvariablen innerhalb dieser Phasen sind obsolet.</li>\n</ul>"}], "trans": [{"from": "FIG-482fe380c7740a11", "to": "FIG-67d04b0db797c7f5", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-67d04b0db797c7f5", "to": "FIG-55ff7f9ff8915e79", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>mode disabling for “old mode”</code>: Neuer horizontaler magentafarbener Blockpfeil oberhalb der Transitions-Runnables hinzugefügt; definiert das Deaktivierungsintervall für den Quellmodus vom Ausgangszustand über alle Übergangsphasen hinweg bis zum Ende der <code>OnEntry</code>-Phase.</li>\n<li><code>mode disabling for “new mode”</code>: Neuer horizontaler blauer Blockpfeil unterhalb der Transitions-Runnables hinzugefügt; definiert den Beginn des Deaktivierungsintervalls für den Zielmodus ab dem Abschluss der letzten Quellmodus-Entität.</li>\n<li><code>mode switch indication</code>: Die vertikale Moduswechsel-Indikation wurde von einer Pfeillinie mit Spitze zu einer durchgehenden vertikalen Bezugslinie bis zur Scheduler-Achse vereinfacht.</li>\n<li><code>ExecutableEntity</code> (Quellmodus): Die über die Indikationslinie hinauslaufende blaue Entität besitzt nun eine gepunktete rechte Begrenzungskante mit einer nach unten gezogenen gepunkteten Hilfslinie, die den exakten Synchronisationspunkt für den Start der <code>OnExit</code>-Phase und des Zielmodus-Disablings markiert.</li>\n</ul>"}, {"from": "FIG-55ff7f9ff8915e79", "to": "FIG-e31faa450d5a3ef0", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
